  const string Scene="Assets/_Modules_/02_Levels/Level04/Imported/Scenes/SampleScene.unity",Q="eco_quantum_projector",P="level04_plasma_gun";
  static Type T(string name)=>Type.GetType(name+", Assembly-CSharp",true);
  static object Get(object o,string name)=>o.GetType().GetProperty(name).GetValue(o);
  static object Call(object o,string name,params object[] args)=>o.GetType().GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);
  static GameObject View(object bag)=> (GameObject)bag.GetType().GetField("weaponModel",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(bag);
  [UnityTest] public IEnumerator CarriedTaskItemHidesBothGunsAndRestoresWithoutInventoryDuplication(){
   var oldBackground=InputSystem.settings.backgroundBehavior;var oldEditor=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;var keyboard=InputSystem.AddDevice<Keyboard>();var mouse=InputSystem.AddDevice<Mouse>();GameObject fakeEnemy=null;PlayerCursor.BeginSimulation(CursorLockMode.Locked);var previousMode=PlayerViewPreference.Mode;object bag=null;Type rt=T("EcoAdventureRuntime");bool addQ=false,addP=false;string[] oldSlots=null;int oldSelected=0,oldMag=0,oldReserve=0;
   try{
    SceneManager.LoadScene(Scene);yield return null;yield return null;bag=rt.GetProperty("Instance").GetValue(null);var has=rt.GetMethod("Has");var slots=(string[])rt.GetField("quickSlots").GetValue(bag);oldSlots=(string[])slots.Clone();oldSelected=(int)rt.GetField("selectedSlot").GetValue(bag);oldMag=(int)rt.GetField("ammoInMagazine").GetValue(bag);oldReserve=(int)rt.GetField("reserveAmmo").GetValue(bag);addQ=!(bool)has.Invoke(bag,new object[]{Q,1});addP=!(bool)has.Invoke(bag,new object[]{P,1});if(addQ)Call(bag,"AddItem",Q,"量子槍",1);if(addP)Call(bag,"AddItem",P,"電漿槍",1);Call(bag,"AssignQuickSlot",0,Q);Call(bag,"AssignQuickSlot",1,P);for(int slot=2;slot<5;slot++){string id="carry_test_slot_"+slot;Call(bag,"AddItem",id,"物品"+slot,1);Call(bag,"AssignQuickSlot",slot,id);}var fullSlots=(string[])slots.Clone();rt.GetField("ammoInMagazine").SetValue(bag,13);rt.GetField("reserveAmmo").SetValue(bag,37);
    var boss=UnityEngine.Object.FindFirstObjectByType(T("BossHealth"));Call(boss,"TakeDamage",5);yield return null;var rec=T("SDGAdventure.Level04.Level04RecycleController").GetProperty("Instance").GetValue(null);var house=UnityEngine.Object.FindFirstObjectByType(T("RecycleHouse"));var items=UnityEngine.Object.FindObjectsOfType(T("RecycleItem")).Cast<Component>().ToArray();Component Item(string name)=>items.Single(i=>i.GetType().GetField("itemType").GetValue(i).ToString()==name);var player=UnityEngine.Object.FindFirstObjectByType<SharedFirstPersonController>();var hud=player.GetComponent<PlayerHudCanvas>();
    foreach(var index in new[]{0,1}){
     rt.GetField("selectedSlot").SetValue(bag,index);PlayerViewPreference.Mode=PlayerViewMode.FirstPerson;yield return null;yield return null;var view=View(bag);Assert.NotNull(view);Assert.IsTrue(view.activeInHierarchy,"Selected gun should be visible");if(index==0){var routine=((MonoBehaviour)bag).StartCoroutine((IEnumerator)Call(bag,"Reload"));rt.GetField("reloadRoutine",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(bag,routine);Assert.IsTrue((bool)rt.GetField("reloading",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(bag));}var item=Item(index==0?"GlassBottle":"Brick");Call(rec,"Interact",item);yield return null;Assert.AreSame(item,Get(rec,"Carried"));Assert.IsTrue(item.gameObject.activeInHierarchy);Assert.IsFalse(view.activeInHierarchy,"Carried item hides held weapon");Assert.AreEqual(view,View(bag),"Hiding must not recreate the view");Assert.That((string)Get(bag,"CarriedTaskItemText"),Does.Contain(index==0?"玻璃瓶 ×1":"磚塊 ×1"));Assert.That(hud.StatusText,Does.Contain("×1"));var shotsField=rt.GetField("totalShots",BindingFlags.NonPublic|BindingFlags.Instance);var plasmaField=rt.GetField("nextPlasmaShotTime",BindingFlags.NonPublic|BindingFlags.Instance);int shots=(int)shotsField.GetValue(bag);plasmaField.SetValue(bag,0f);InputSystem.QueueStateEvent(mouse,new MouseState().WithButton(MouseButton.Left));yield return null;InputSystem.QueueStateEvent(mouse,new MouseState());yield return null;Assert.AreEqual(shots,shotsField.GetValue(bag),"Carrying blocks quantum fire");Assert.AreEqual(0f,plasmaField.GetValue(bag),"Carrying blocks plasma fire");var quickText=(string)Call(bag,"QuickSlotDisplay",index);Assert.That(quickText,Does.Contain(index==0?"玻璃瓶 ×1":"磚塊 ×1"));Assert.That(quickText,Does.Not.Contain("▼"));CollectionAssert.AreEqual(fullSlots,slots);if(index==0){var second=Item("Tire");var camera=Camera.main;second.transform.position=camera.transform.position+camera.transform.forward*1.3f;Physics.SyncTransforms();yield return null;var interactor=player.GetComponent<PlayerInteractor>();var target=interactor.FindTarget();Assert.NotNull(target,"Second item should remain targetable for the warning");Assert.That(target.Prompt,Does.Contain("請先放下目前攜帶的物品"));interactor.TryInteract();Assert.AreSame(item,Get(rec,"Carried"));Assert.IsTrue(second.gameObject.activeInHierarchy);Assert.IsTrue((bool)Call(rec,"CanInteract",item)==false);}Assert.AreEqual(index,rt.GetField("selectedSlot").GetValue(bag));if(index==0){Assert.IsFalse((bool)rt.GetField("reloading",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(bag));yield return new WaitForSeconds(1.5f);Assert.AreEqual(13,rt.GetField("ammoInMagazine").GetValue(bag));Assert.AreEqual(37,rt.GetField("reserveAmmo").GetValue(bag));}
     PlayerViewPreference.Mode=PlayerViewMode.ThirdPerson;yield return null;Assert.IsFalse(view.activeInHierarchy);Call(bag,"ToggleInventory");yield return null;Assert.IsTrue((bool)rt.GetField("inventoryOpen",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(bag));Assert.IsNotEmpty((string)Get(bag,"CarriedTaskItemText"));Call(bag,"ToggleInventory");yield return null;Assert.AreEqual(view,View(bag));Assert.IsFalse(view.activeInHierarchy);
     if(index==0){Assert.IsTrue((bool)Call(rec,"DropCarried"));yield return null;Assert.IsNull(Get(rec,"Carried"));Assert.IsEmpty((string)Get(bag,"CarriedTaskItemText"));Assert.That((string)Call(bag,"QuickSlotDisplay",index),Does.Not.Contain("任務："));Assert.That(hud.StatusText,Does.Not.Contain("攜帶中"));Assert.AreSame(view,View(bag));Assert.IsTrue(view.activeInHierarchy);}else{Call(rec,"Interact",new object[]{null});yield return null;Assert.AreEqual(1,Get(house,"CompletedQuestions"));Assert.IsNull(Get(rec,"Carried"));Assert.IsEmpty((string)Get(bag,"CarriedTaskItemText"));Assert.That((string)Call(bag,"QuickSlotDisplay",index),Does.Not.Contain("任務："));Assert.That(hud.StatusText,Does.Not.Contain("攜帶中"));Assert.AreSame(view,View(bag));Assert.IsTrue(view.activeInHierarchy);}
    }
    var wrong=Item("Motherboard");var current=View(bag);Call(rec,"Interact",wrong);yield return null;Assert.IsFalse(current.activeInHierarchy);LogAssert.Expect(LogType.Warning,"答案錯誤！物品退回地面。");Call(rec,"Interact",new object[]{null});yield return null;Assert.AreEqual(2,Get(house,"CompletedQuestions"));Assert.IsNull(Get(rec,"Carried"));Assert.IsTrue(current.activeInHierarchy);Assert.IsEmpty((string)Get(bag,"CarriedTaskItemText"));Assert.That((string)Call(bag,"QuickSlotDisplay",1),Does.Not.Contain("任務："));Assert.That(hud.StatusText,Does.Not.Contain("攜帶中"));Assert.IsTrue(wrong.gameObject.activeInHierarchy);Assert.IsTrue((bool)has.Invoke(bag,new object[]{Q,1}));Assert.IsTrue((bool)has.Invoke(bag,new object[]{P,1}));Assert.AreEqual(13,rt.GetField("ammoInMagazine").GetValue(bag));Assert.AreEqual(37,rt.GetField("reserveAmmo").GetValue(bag));Assert.AreEqual(Q,slots[0]);Assert.AreEqual(P,slots[1]);Assert.AreEqual(1,rt.GetField("selectedSlot").GetValue(bag));CollectionAssert.AreEqual(fullSlots,slots);PlayerViewPreference.Mode=PlayerViewMode.FirstPerson;yield return null;var tyre=Item("Tire");var disc=Item("Disc");Vector3 worldScale=tyre.transform.lossyScale;Call(rec,"Interact",tyre);yield return null;Assert.AreSame(tyre,Get(rec,"Carried"));Call(rec,"Interact",disc);Assert.AreSame(tyre,Get(rec,"Carried"));Assert.IsTrue(disc.gameObject.activeInHierarchy);var rendered=tyre.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&!r.name.StartsWith("V11_HintOverlay_")).ToArray();Assert.IsNotEmpty(rendered);var heldBounds=rendered[0].bounds;foreach(var r in rendered.Skip(1))heldBounds.Encapsulate(r.bounds);Assert.LessOrEqual(Mathf.Max(heldBounds.size.x,Mathf.Max(heldBounds.size.y,heldBounds.size.z)),.51f,"Held tire must not obstruct the entire view");float minX=2f,maxX=-1f,minY=2f,maxY=-1f;for(int corner=0;corner<8;corner++){var sign=new Vector3((corner&1)==0?-1:1,(corner&2)==0?-1:1,(corner&4)==0?-1:1);var v=Camera.main.WorldToViewportPoint(heldBounds.center+Vector3.Scale(heldBounds.extents,sign));if(v.z>Camera.main.nearClipPlane){minX=Mathf.Min(minX,v.x);maxX=Mathf.Max(maxX,v.x);minY=Mathf.Min(minY,v.y);maxY=Mathf.Max(maxY,v.y);}}Assert.IsFalse(minX<=.5f&&maxX>=.5f&&minY<=.5f&&maxY>=.5f,$"Tire bounds obscure crosshair: {minX},{maxX},{minY},{maxY}");Assert.That((string)Call(bag,"QuickSlotDisplay",1),Does.Contain("輪胎 ×1"));Assert.That((string)Get(bag,"CarriedTaskItemText"),Does.Contain("輪胎 ×1"));Assert.IsTrue((bool)Call(rec,"DropCarried"));yield return null;Assert.Less(Vector3.Distance(worldScale,tyre.transform.lossyScale),.001f,"World scale must be restored on drop");Assert.That((string)Call(bag,"QuickSlotDisplay",1),Does.Not.Contain("任務："));Assert.IsEmpty((string)Get(bag,"CarriedTaskItemText"));CollectionAssert.AreEqual(fullSlots,slots);Call(rec,"Interact",disc);yield return null;Assert.AreSame(disc,Get(rec,"Carried"));fakeEnemy=new GameObject("Test damage source");var fakeBoss=fakeEnemy.AddComponent(T("BossHealth"));yield return null;var health=player.GetComponent(T("SDGAdventure.Level04.Level04PlayerHealth"));Assert.IsTrue((bool)Call(health,"TryBossHit",fakeBoss,100,player.transform.position-Vector3.forward));yield return null;Assert.IsNull(Get(rec,"Carried"),"Death clears carried item");Assert.IsEmpty((string)Get(bag,"CarriedTaskItemText"));Assert.That((string)Call(bag,"QuickSlotDisplay",1),Does.Not.Contain("任務："));Assert.IsTrue(disc.gameObject.activeInHierarchy);Assert.NotNull(GameObject.Find("Level04FailureCanvas"));
   }finally{if(bag!=null&&oldSlots!=null){for(int slot=2;slot<5;slot++)Call(bag,"Consume","carry_test_slot_"+slot,1);if(addQ)Call(bag,"Consume",Q,1);if(addP)Call(bag,"Consume",P,1);Array.Copy(oldSlots,(string[])rt.GetField("quickSlots").GetValue(bag),oldSlots.Length);rt.GetField("selectedSlot").SetValue(bag,oldSelected);rt.GetField("ammoInMagazine").SetValue(bag,oldMag);rt.GetField("reserveAmmo").SetValue(bag,oldReserve);}if(fakeEnemy)UnityEngine.Object.DestroyImmediate(fakeEnemy);PlayerViewPreference.Mode=previousMode;PlayerInputService.Instance.SetContext(PlayerInputContext.Gameplay);PlayerCursor.EndSimulation();InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);InputSystem.settings.backgroundBehavior=oldBackground;InputSystem.settings.editorInputBehaviorInPlayMode=oldEditor;Time.timeScale=1;}
  }
